class Solution {
    vector<vector<int>> edges;
    vector<int> matched;
    vector<bool> visited;
    bool augment(int boy) {
        for (int girl : edges[boy]) {
            if (visited[girl]) continue;
            visited[girl] = true;
            if (matched[girl] == -1 || augment(matched[girl])) {
                matched[girl] = boy;
                return true;
            }
        }
        return false;
    }
public:
    int maximumInvitations(vector<vector<int>>& grid) {
        int boys = grid.size(), girls = grid[0].size();
        edges.assign(boys, {});
        for (int i = 0; i < boys; ++i) {
            for (int j = 0; j < girls; ++j) if (grid[i][j]) edges[i].push_back(j);
        }
        matched.assign(girls, -1);
        int answer = 0;
        for (int i = 0; i < boys; ++i) {
            visited.assign(girls, false);
            if (augment(i)) ++answer;
        }
        return answer;
    }
};
